import FinalStateNode from "./FinalStateNode";
import { useSelector, useDispatch } from 'react-redux';
import { Box, Stack } from "@mui/joy";
import { ArrowForward } from "@mui/icons-material";

export default function FinalStateSelector() {
    const finalState = useSelector(state => state.finalState);
    if (!finalState.nodes) {
        return (
            <div>
            </div>
        )
    }
    return (
        <div>
            <Stack spacing={14} direction="row" justifyContent={"space-between"}>
            <FinalStateNode key={0} node={0} decaying={true}/>
            <Box sx={{ display: 'flex', alignItems: 'center', flexGrow: 1 }}>
                <ArrowForward/></Box>
                <Stack spacing={2} direction="row" justifyContent={"space-between"}>
                    {finalState.nodes.map(n => <FinalStateNode key={n} node={n} />)}                   
                </Stack>
            </Stack>
        </div>
    )
}