
import { Grid, Card, Select, CardContent, Button } from '@mui/joy';
import { useDispatch, useSelector } from 'react-redux'
import Option from '@mui/joy/Option';
import Tooltip from '@mui/joy/Tooltip';
import Stack from '@mui/joy/Stack';
import { MathJax } from 'better-react-mathjax';
import { useState } from 'react';
import { API_PATH } from '../Internal/api.js';
import { extractIsobars } from '../Internal/helpers.js';



export default function DecaySelector(){
    const dispatch = useDispatch();
    const decay = useSelector((state) => state.decay);
    const locked = useSelector(state => state.decayLock);

    const [showTooltip, setShowTooltip] = useState(true);

    const handleNewTopologies = (topologies) => {
        dispatch({ type: 'SET_GRAPH', payload: topologies }); // Dispatch the action
    };
    const handleNewFinalState = (nodes) => {
        dispatch({ type: 'SET_FINAL_STATE', payload: nodes }); // Dispatch the action
        dispatch({ type: 'SET_TREE_MASK', payload: {} }); // Dispatch the action
        dispatch({ type: 'SET_GRAPH_CHECK', payload: {} }); // Dispatch the action
    };

    const handleNewIsobars = (isobars) => {
        dispatch({ type: 'SET_ISOBAR', payload: isobars }); // Dispatch the action
    }
    const handleNewDecay = (n) => {
        dispatch({ type: 'SET_DECAY', payload: n }); // Dispatch the action
        dispatch({ type: 'SET_MAIN_GRAPH', payload: {} }); // Dispatch the action
        const api_query = API_PATH + "topologies?n="+ n;
        fetch(api_query)
        .then(response => {
            if (!response.ok) {
            throw new Error('Network response was not ok');
            }
            return response.json();
        })
        .then(data => {
            const isobars = {};
            data.topologies.forEach((topology, index) => {
                extractIsobars(topology[0], isobars);
                extractIsobars(topology[1], isobars);
            });
            handleNewIsobars(isobars);
            handleNewTopologies(data.topologies);
        })
        .catch(error => {
            console.error('Error:', error);
        });
        handleNewFinalState(Array.from({ length: n }, (_, i) => i + 1));


    };

    if (decay === null || decay === undefined ) {
        handleNewDecay(3); // Default to 3-particle decay if none is set
        // return null; // Return null to avoid rendering the component until decay is set
    }

    return (
        <Stack >
            <Tooltip title={showTooltip ? "Select how many particles the decay should be into" : null}>
            <Card>
                <Select onChange={(e, newValue) => handleNewDecay(newValue)} defaultValue={decay}disabled={locked} placeholder={"N-Particle Decay"} onListboxOpenChange={(e) => setShowTooltip(!showTooltip)} value={decay}>
                    <Option value={3}>
                        <MathJax>
                            {"`0 \\rightarrow 1 \\, 2 \\, 3`"}
                        </MathJax>
                    </Option>
                    <Option value={4}>
                        <MathJax>
                            {"`0 \\rightarrow 1 \\, 2 \\, 3 \\, 4`"}
                        </MathJax>
                    </Option>
                    <Option value={5}>
                        <MathJax>
                            {"`0 \\rightarrow 1 \\, 2 \\, 3 \\, 4 \\, 5`"}
                        </MathJax>
                    </Option>
                    <Option value={6}>
                        <MathJax>
                            {"`0 \\rightarrow 1 \\, 2 \\, 3 \\, 4 \\, 5 \\, 6`"}
                        </MathJax>
                    </Option>
                </Select>
            </Card>
            </Tooltip>
        </Stack>
    )
};
